'use client'

import Editor from '@monaco-editor/react'
import { useEffect, useState } from 'react'
import { getSupabaseBrowserClient } from '@/lib/supabase'
import { ArrowLeft, ArrowRight, Bell, Check, ClipboardCheck, Code2, Copy, Gamepad2, LockKeyhole, Play, Plus, Radio, Send, ShieldCheck, Timer, Trophy, Users, Video, Wifi, X, Zap } from 'lucide-react'

type View = 'home' | 'profile' | 'hireme' | 'admin' | 'check' | 'assessment' | 'codemates' | 'codemates-brief' | 'codemates-check' | 'rooms' | 'lobby' | 'game' | 'results'
const questions = ['Multiple choice', 'Written response', 'SQL challenge', 'Debugging']
const players = [{ name: 'Maya Chen', initials: 'MC', color: 'bg-cyan-400', score: 840, status: 'Solving' }, { name: 'Alex Rivera', initials: 'AR', color: 'bg-amber-300', score: 790, status: 'Reviewing' }, { name: 'You', initials: 'YO', color: 'bg-fuchsia-400', score: 720, status: 'Coding' }]

export default function Home() {
  const [view, setView] = useState<View>('home')
  const [light, setLight] = useState(false)
  const [question, setQuestion] = useState(0)
  const [paused, setPaused] = useState(false)
  const [ready, setReady] = useState(false)
  const [chat, setChat] = useState('')
  const [messages, setMessages] = useState(['Maya: Let’s split the edge cases.', 'Alex: I’ll check the test runner.'])
  const [roomCode, setRoomCode] = useState('ASYNC-77')
  const [userEmail, setUserEmail] = useState<string | null>(null)
  useEffect(() => {
    const supabase = getSupabaseBrowserClient()
    supabase.auth.getUser().then(({ data }) => setUserEmail(data.user?.email ?? null))
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => setUserEmail(session?.user?.email ?? null))
    return () => listener.subscription.unsubscribe()
  }, [])
  const nav = (next: View) => { setView(next); setPaused(false) }
  const joinLobby = (code: string) => { setRoomCode(code.trim().toUpperCase() || 'ASYNC-77'); nav('lobby') }
  const sendMessage = () => { if (!chat.trim()) return; setMessages([...messages, `You: ${chat.trim()}`]); setChat('') }
  return <main className={`min-h-screen transition-colors ${light ? 'bg-[#f4ead0] text-[#18202b]' : 'bg-[#10131d] text-[#f7f0dc]'}`}>
    {view !== 'home' && <header className="border-b-4 border-[#4d3b2b] bg-[#f4ead0] px-5 py-3 text-[#18202b]"><div className="mx-auto flex max-w-[1440px] items-center justify-between gap-4"><button onClick={() => nav('home')} className="flex items-center gap-3 text-left"><span className="grid size-9 place-items-center border-2 border-[#4d3b2b] bg-[#e8a33a] text-[#18202b]"><Zap className="size-5 fill-current" /></span><span className="font-mono text-sm font-bold">HireMe<span className="text-[#d45b32]">.app</span></span></button><div className="flex items-center gap-2"><button onClick={() => setLight(!light)} className="border-2 border-[#4d3b2b] px-3 py-2 font-mono text-xs">{light ? 'DARK' : 'LIGHT'}</button></div></div></header>}
    <div className="mx-auto max-w-[1440px]">{view === 'home' && <><Landing nav={nav} /><AuthPanel userEmail={userEmail} /></>}{view === 'profile' && <CandidateIntake nav={nav} />}{view === 'hireme' && <HireInvite nav={nav} />}{view === 'admin' && <AdminPortal nav={nav} />}{view === 'check' && <SystemCheck ready={ready} setReady={setReady} nav={nav} />}{view === 'assessment' && <Assessment question={question} setQuestion={setQuestion} paused={paused} setPaused={setPaused} nav={nav} />}{view === 'codemates' && <CodeMatesHome nav={nav} joinLobby={joinLobby} />}{view === 'codemates-brief' && <CodeMatesBrief nav={nav} />}{view === 'codemates-check' && <CodeMatesCheck ready={ready} setReady={setReady} nav={nav} />}{view === 'rooms' && <LiveRooms nav={nav} joinLobby={joinLobby} />}{view === 'lobby' && <Lobby nav={nav} roomCode={roomCode} />}{view === 'game' && <Game chat={chat} setChat={setChat} messages={messages} sendMessage={sendMessage} nav={nav} />}{view === 'results' && <Results nav={nav} />}</div>
  </main>
}
function AuthPanel({ userEmail }: { userEmail: string | null }) {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [mode, setMode] = useState<'sign-in' | 'sign-up'>('sign-in')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async () => {
    setBusy(true); setError('')
    const supabase = getSupabaseBrowserClient()
    const result = mode === 'sign-in'
      ? await supabase.auth.signInWithPassword({ email, password })
      : await supabase.auth.signUp({ email, password, options: { emailRedirectTo: process.env.NEXT_PUBLIC_DEV_SUPABASE_REDIRECT_URL ?? `${window.location.origin}/auth/callback` } })
    if (result.error) setError(result.error.message.includes('Invalid') ? 'Invalid email or password.' : 'Unable to complete authentication.')
    setBusy(false)
  }
  if (userEmail) return <div className="mx-auto mb-8 flex max-w-5xl items-center justify-between border-2 border-[#4d3b2b] bg-[#f4ead0] px-4 py-3 font-mono text-xs text-[#18202b]"><span>SIGNED IN · {userEmail}</span><button onClick={() => getSupabaseBrowserClient().auth.signOut()} className="border-2 border-[#18202b] px-3 py-2">SIGN OUT</button></div>
  return <section className="mx-auto mb-8 max-w-5xl border-2 border-[#4d3b2b] bg-[#f4ead0] p-5 text-[#18202b]"><div className="flex flex-wrap items-end gap-3"><label className="grid flex-1 gap-1 font-mono text-xs">EMAIL<input value={email} onChange={e => setEmail(e.target.value)} type="email" className="border-2 border-[#4d3b2b] bg-[#fff9e8] px-3 py-2" /></label><label className="grid flex-1 gap-1 font-mono text-xs">PASSWORD<input value={password} onChange={e => setPassword(e.target.value)} type="password" className="border-2 border-[#4d3b2b] bg-[#fff9e8] px-3 py-2" /></label><button disabled={busy} onClick={submit} className="border-2 border-[#18202b] bg-[#18202b] px-4 py-3 font-mono text-xs text-[#f4ead0]">{busy ? 'WORKING…' : mode === 'sign-in' ? 'SIGN IN' : 'CREATE ACCOUNT'}</button><button onClick={() => setMode(mode === 'sign-in' ? 'sign-up' : 'sign-in')} className="px-2 py-3 font-mono text-xs underline">{mode === 'sign-in' ? 'New candidate?' : 'Already registered?'}</button></div>{error && <p className="mt-3 font-mono text-xs text-[#d9362b]">{error}</p>}<p className="mt-3 font-mono text-[10px] text-[#685744]">Sign in to save applications, join rooms, submit code, and access recruiter data.</p></section>
}

function Kicker({ children, pink = false }: { children: React.ReactNode; pink?: boolean }) { return <div className={`mb-3 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.22em] ${pink ? 'text-fuchsia-300' : 'text-cyan-300'}`}><span className="size-1.5 rounded-full bg-current" />{children}</div> }
function Button({ children, onClick, pink = false, ghost = false, disabled = false }: { children: React.ReactNode; onClick?: () => void; pink?: boolean; ghost?: boolean; disabled?: boolean }) { return <button onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold transition active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-40 ${ghost ? 'border border-white/15 text-white/75 hover:bg-white/10' : pink ? 'bg-fuchsia-400 text-[#190b1b] hover:bg-fuchsia-300' : 'bg-cyan-300 text-[#061017] hover:bg-cyan-200'}`}>{children}</button> }
function Landing({ nav }: { nav: (v: View) => void }) { return <section className="landing-shell"><div className="landing-topbar"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center border-2 border-[#4d3b2b] bg-[#e8a33a] text-[#18202b]"><Zap className="size-5 fill-current" /></span><span className="font-mono text-sm font-bold tracking-tight">hireme<span className="text-[#d45b32]">.app</span></span></div><div className="hidden items-center gap-5 font-mono text-[11px] uppercase tracking-[.18em] text-[#685744] sm:flex"><span>workspace_01</span><span className="size-2 rounded-full bg-[#4d9a6a]" /><span>online</span></div></div><div className="landing-intro"><div className="font-mono text-xs uppercase tracking-[.2em] text-[#685744]">Choose your room</div><h1 className="mt-4 text-balance font-mono text-4xl font-bold tracking-[-.08em] sm:text-6xl">Build alone.<br /><span className="text-[#d45b32]">Build together.</span></h1><p className="mt-5 max-w-lg text-sm leading-6 text-[#685744]">A focused home for proving what you can do and finding the people you want to build with.</p></div><div className="landing-choices"><button className="choice-panel choice-hire" onClick={() => nav('profile')}><div className="choice-number">01</div><div><div className="font-mono text-xs uppercase tracking-[.2em] text-[#685744]">For your next opportunity</div><h2 className="mt-3 font-mono text-4xl font-bold">Hire Me</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[#685744]">Show your thinking through a clear, fair assessment built around real work.</p></div><span className="choice-arrow">→</span></button><button className="choice-panel choice-mates" onClick={() => nav('codemates')}><div className="choice-number">02</div><div><div className="font-mono text-xs uppercase tracking-[.2em] text-[#685744]">For your next build session</div><h2 className="mt-3 font-mono text-4xl font-bold">CodeMates</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[#d7c9ad]">Enter a live room, solve problems, and make something memorable with your crew.</p></div><span className="choice-arrow">→</span></button></div><div className="landing-footer"><span>SELECT A PATH TO CONTINUE</span><span className="hidden sm:inline">© 2026 / SKILLS MADE VISIBLE</span></div></section> }
function Dashboard({ nav }: { nav: (v: View) => void }) { return <div className="space-y-10"><section className="grid items-end gap-8 lg:grid-cols-[1.3fr_.7fr]"><div><Kicker>Personal workspace</Kicker><h1 className="max-w-3xl text-balance text-4xl font-semibold tracking-[-.04em] sm:text-6xl">Prove your skills.<br /><span className="text-cyan-300">Build with your team.</span></h1><p className="mt-5 max-w-xl text-base leading-7 text-white/55">One focused workspace for high-signal hiring assessments and multiplayer coding rooms that make learning feel social.</p></div><div className="border-l border-white/10 pl-5 text-sm text-white/55"><div className="flex items-center gap-2 text-white"><span className="text-cyan-300">◈</span>Weekly momentum</div><div className="mt-4 text-3xl font-semibold text-white">72<span className="text-base text-white/35"> / 100</span></div><div className="mt-3 h-1.5 rounded-full bg-white/10"><div className="h-full w-[72%] rounded-full bg-cyan-300" /></div><div className="mt-2 text-xs">+18% from last week</div></div></section><section className="grid gap-5 lg:grid-cols-2"><ProductCard hire icon={<ClipboardCheck />} title="HireMe" description="Structured assessments that show how candidates really think, debug, and communicate." bullets={['Proctored, fair assessments', 'Signal-rich recruiter review', 'Question types that match the role']} action="Open assessment" onClick={() => nav('hireme')} /><ProductCard icon={<Gamepad2 />} title="CodeMates" description="Drop into a retro multiplayer room, solve real problems, and level up together." bullets={['Live shared editor and presence', 'Team rounds with instant scoring', 'Voice, chat, and reconnect states']} action="Enter the arcade" onClick={() => nav('codemates')} /></section><section className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl border border-white/10 bg-white/[.035] p-5"><div className="flex items-center justify-between"><div><Kicker>Recent activity</Kicker><h2 className="text-lg font-semibold">Keep the streak alive</h2></div><span className="text-xs text-cyan-300">View all</span></div><div className="mt-5 divide-y divide-white/10">{[['CodeMates room', 'Async arena · 3 players', '8 min ago', '84 XP'], ['Frontend assessment', 'Acme Labs · completed', 'Yesterday', '92 / 100'], ['SQL sprint', 'Practice set · 12 questions', 'Mon, 14:30', '68 XP']].map(([a, b, c, d]) => <div className="flex items-center justify-between gap-4 py-4" key={a}><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-white/7 text-cyan-300"><Code2 className="size-4" /></div><div><div className="text-sm font-medium">{a}</div><div className="text-xs text-white/40">{b}</div></div></div><div className="text-right"><div className="text-xs">{d}</div><div className="text-[10px] text-white/35">{c}</div></div></div>)}</div></div><div className="rounded-2xl border border-white/10 bg-[#111923] p-5"><Kicker pink>Your toolkit</Kicker><h2 className="text-lg font-semibold">Ready for the next challenge?</h2><div className="mt-5 grid grid-cols-2 gap-3">{[['Brain circuits', '12 skills'], ['Repositories', '4 connected'], ['Focus time', '2h 18m'], ['Rank', '#184']].map(([a, b]) => <div className="rounded-xl border border-white/8 bg-white/[.03] p-3" key={a}><div className="text-xs text-white/45">{a}</div><div className="mt-1 text-sm font-semibold">{b}</div></div>)}</div><Button ghost>Manage connections</Button></div></section></div> }
function ProductCard({ hire = false, icon, title, description, bullets, action, onClick }: { hire?: boolean; icon: React.ReactNode; title: string; description: string; bullets: string[]; action: string; onClick: () => void }) { return <article className={`rounded-2xl border p-6 ${hire ? 'border-cyan-300/25 bg-[#101d25]' : 'border-fuchsia-300/25 bg-[#211722]'}`}><div className="flex items-start justify-between"><div className={`grid size-11 place-items-center rounded-xl ${hire ? 'bg-cyan-300 text-[#061017]' : 'bg-fuchsia-400 text-[#190b1b]'}`}>{icon}</div><span className="rounded-full border border-white/10 px-2 py-1 text-[10px] uppercase tracking-widest text-white/45">{hire ? 'signal' : 'social'}</span></div><h2 className="mt-8 text-2xl font-semibold">{title}</h2><p className="mt-2 max-w-md text-sm leading-6 text-white/55">{description}</p><div className="mt-6 grid gap-2">{bullets.map(b => <div className="flex items-center gap-2 text-xs text-white/65" key={b}><Check className="size-3.5 text-cyan-300" />{b}</div>)}</div><Button pink={!hire} onClick={onClick}>{action}<ArrowRight className="size-4" /></Button></article> }
function CandidateIntake({ nav }: { nav: (v: View) => void }) {
  const [name, setName] = useState('')
  const [linkedin, setLinkedin] = useState('')
  const [github, setGithub] = useState('')
  const [skills, setSkills] = useState('')
  const canContinue = name.trim() && (linkedin.trim() || github.trim()) && skills.trim()

  return <div className="mx-auto max-w-3xl">
    <Back onClick={() => nav('home')} label="Back to workspace" />
    <div className="mx-auto max-w-2xl">
      <Kicker>Candidate profile · Step 1 of 2</Kicker>
      <h1 className="text-4xl font-semibold tracking-tight sm:text-6xl">Tell us where to find your work.</h1>
      <p className="mt-5 max-w-xl text-base leading-7 text-white/55">A quick profile before the assessment. Add your public links and skills manually; we will use them to prepare your candidate profile for recruiter review.</p>
      <div className="mt-10 grid gap-6 rounded-2xl border border-white/10 bg-[#111923] p-6 sm:p-8">
        <label className="grid gap-2 text-sm font-medium">Full name<input value={name} onChange={e => setName(e.target.value)} placeholder="Maya Chen" className="border border-white/15 bg-white/[.04] px-4 py-3 text-sm outline-none transition placeholder:text-white/25 focus:border-cyan-300" /></label>
        <label className="grid gap-2 text-sm font-medium">LinkedIn profile URL<span className="text-xs font-normal text-white/40">Optional if you use GitHub instead</span><input value={linkedin} onChange={e => setLinkedin(e.target.value)} placeholder="linkedin.com/in/your-name" type="url" className="border border-white/15 bg-white/[.04] px-4 py-3 text-sm outline-none transition placeholder:text-white/25 focus:border-cyan-300" /></label>
        <label className="grid gap-2 text-sm font-medium">GitHub profile URL<span className="text-xs font-normal text-white/40">Optional if you use LinkedIn instead</span><input value={github} onChange={e => setGithub(e.target.value)} placeholder="github.com/your-handle" type="url" className="border border-white/15 bg-white/[.04] px-4 py-3 text-sm outline-none transition placeholder:text-white/25 focus:border-cyan-300" /></label>
        <label className="grid gap-2 text-sm font-medium">Skills<span className="text-xs font-normal text-white/40">Separate skills with commas. Example: React, TypeScript, Node.js</span><textarea value={skills} onChange={e => setSkills(e.target.value)} placeholder="React, TypeScript, Node.js" rows={3} className="resize-none border border-white/15 bg-white/[.04] px-4 py-3 text-sm leading-6 outline-none transition placeholder:text-white/25 focus:border-cyan-300" /></label>
        <div className="flex flex-col gap-3 border-t border-white/10 pt-5 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs leading-5 text-white/40">We do not import or scrape profile data. You stay in control of what you submit.</p><Button onClick={() => nav('hireme')} disabled={!canContinue}>Continue to assessment <ArrowRight className="size-4" /></Button></div>
        {!canContinue && <p className="text-xs text-amber-300">Add your name, one profile link, and at least one skill to continue.</p>}
      </div>
    </div>
  </div>
}

function HireInvite({ nav }: { nav: (v: View) => void }) { return <div className="mx-auto max-w-5xl"><Back onClick={() => nav('home')} label="Back to workspace" /><div className="grid gap-8 lg:grid-cols-[1fr_.75fr]"><div><Kicker>Invitation · Frontend engineer</Kicker><h1 className="text-4xl font-semibold tracking-tight sm:text-5xl">Show us how you think.</h1><p className="mt-5 max-w-xl text-lg leading-8 text-white/55">You’ve been invited to complete an assessment for <span className="text-white">Northstar Systems</span>. No trick questions. Just a clear space to show your craft.</p><div className="mt-8 grid gap-3 sm:grid-cols-3">{[['45 min', 'time limit'], ['4', 'questions'], ['Senior', 'level']].map(([a, b]) => <div className="rounded-xl border border-white/10 bg-white/[.03] p-4" key={a}><div className="text-xl font-semibold">{a}</div><div className="mt-1 text-xs uppercase tracking-wider text-white/35">{b}</div></div>)}</div><div className="mt-8 flex flex-wrap items-center gap-3"><Button onClick={() => nav('check')}>Begin system check <ArrowRight className="size-4" /></Button><button onClick={() => nav('admin')} className="border border-white/15 px-4 py-3 text-sm text-white/55 transition hover:border-white/35 hover:text-white">Recruiter portal</button></div></div><aside className="rounded-2xl border border-white/10 bg-[#111923] p-6"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-xl bg-white text-black"><Code2 className="size-5" /></div><div><div className="font-semibold">Northstar Systems</div><div className="text-xs text-white/45">Product engineering</div></div></div><div className="my-6 h-px bg-white/10" /><h3 className="text-sm font-semibold">Before you begin</h3><div className="mt-4 grid gap-4">{[['Monitor your own time', Timer], ['Camera and screen share', Video], ['No backtracking', LockKeyhole], ['Your work stays private', ShieldCheck]].map(([text, Icon]) => <div className="flex items-center gap-3 text-sm text-white/60" key={text as string}><Icon className="size-4 text-cyan-300" />{text as string}</div>)}</div></aside></div></div> }
function Back({ onClick, label }: { onClick: () => void; label: string }) { return <button onClick={onClick} className="mb-8 flex items-center gap-2 text-sm text-white/45 hover:text-white"><ArrowLeft className="size-4" />{label}</button> }
function SystemCheck({ ready, setReady, nav }: { ready: boolean; setReady: (v: boolean) => void; nav: (v: View) => void }) { return <div className="mx-auto max-w-4xl"><Back onClick={() => nav('hireme')} label="Assessment details" /><div className="text-center"><Kicker>Secure environment check</Kicker><h1 className="text-4xl font-semibold tracking-tight">Let’s get you set up.</h1><p className="mx-auto mt-4 max-w-lg text-white/50">We’ll check the essentials before your timer starts. Nothing is recorded until you give consent.</p></div><div className="mt-10 grid gap-5 md:grid-cols-2"><div className="overflow-hidden rounded-2xl border border-white/10 bg-[#111923]"><div className="flex aspect-video items-center justify-center bg-[#18232b]"><div className="grid size-24 place-items-center rounded-full border border-cyan-300/50 bg-cyan-300/10"><Video className="size-8 text-cyan-300" /></div></div><div className="flex items-center justify-between p-4"><div><div className="text-sm font-semibold">Camera preview</div><div className="mt-1 text-xs text-white/40">Front camera detected</div></div><Check className="size-5 text-cyan-300" /></div></div><div className="rounded-2xl border border-white/10 bg-[#111923] p-5">{[['Camera', true], ['Microphone', true], ['Screen sharing', true], ['Browser permissions', ready]].map(([label, ok]) => <div key={label as string} className="flex items-center justify-between border-b border-white/8 py-4 text-sm"><span className="text-white/65">{label as string}</span><span className={`flex items-center gap-2 text-xs ${ok ? 'text-cyan-300' : 'text-amber-300'}`}>{ok ? <Check className="size-4" /> : <span className="size-2 rounded-full bg-current" />}{ok ? 'Ready' : 'Waiting'}</span></div>)}<label className="mt-5 flex cursor-pointer items-start gap-3 text-xs leading-5 text-white/45"><input type="checkbox" checked={ready} onChange={e => setReady(e.target.checked)} className="mt-1 accent-cyan-300" />I consent to the assessment recording and understand that leaving fullscreen may pause my session.</label></div></div><div className="flex justify-center"><Button onClick={() => ready && nav('assessment')}>Continue to assessment <ArrowRight className="size-4" /></Button></div></div> }
function Assessment({ question, setQuestion, paused, setPaused, nav }: { question: number; setQuestion: (n: number) => void; paused: boolean; setPaused: (v: boolean) => void; nav: (v: View) => void }) { return <div className="fixed inset-0 z-30 flex flex-col bg-[#0b1118]"><div className="flex items-center justify-between border-b border-white/10 px-5 py-3"><div className="font-semibold">Northstar <span className="text-white/35">/</span> Assessment</div><div className="flex items-center gap-4"><span className="font-mono text-sm text-amber-300">32:18</span><Button ghost onClick={() => setPaused(true)}>Pause session</Button></div></div><div className="flex min-h-0 flex-1"><aside className="hidden w-64 shrink-0 border-r border-white/10 p-5 md:block"><div className="text-[10px] uppercase tracking-widest text-white/35">Questions</div><div className="mt-5 grid gap-2">{questions.map((item, i) => <button key={item} onClick={() => i <= question && setQuestion(i)} className={`flex items-center gap-3 rounded-lg p-3 text-left text-xs ${i === question ? 'bg-cyan-300/10 text-cyan-200' : 'text-white/45'}`}><span className="grid size-6 place-items-center rounded-md border border-white/15">{i < question ? <Check className="size-3" /> : i + 1}</span>{item}</button>)}</div><div className="mt-10 border-t border-white/10 pt-5 text-xs text-white/35"><div className="flex items-center gap-2"><Radio className="size-3 text-cyan-300" />Integrity monitor active</div><div className="mt-3 flex items-center gap-2"><Wifi className="size-3 text-cyan-300" />Connection stable</div></div></aside><section className="min-w-0 flex-1 overflow-y-auto p-5 sm:p-10"><div className="mx-auto max-w-4xl"><div className="flex justify-between text-xs text-white/40"><span>Question {question + 1} of 4</span><span className="font-mono">04:12</span></div><h1 className="mt-5 max-w-3xl text-2xl font-semibold sm:text-4xl">{question === 0 ? 'Which strategy keeps a distributed cache consistent?' : question === 1 ? 'Explain how you would design a resilient checkout flow.' : question === 2 ? 'Find the three highest-value customers this quarter.' : 'Fix the race condition in this async queue.'}</h1>{question === 0 ? <div className="mt-10 grid gap-3">{['A write-through cache with versioned invalidation', 'A single global cache with no expiry', 'Client-side memoization only', 'A queue that retries every request'].map((a, i) => <button key={a} onClick={() => setQuestion(1)} className="flex items-center gap-4 rounded-xl border border-white/10 bg-white/[.03] p-5 text-left text-sm text-white/70 hover:border-cyan-300/50"><span className="grid size-7 place-items-center rounded-lg border border-white/15 text-xs">{String.fromCharCode(65 + i)}</span>{a}</button>)}</div> : <textarea className="mt-10 min-h-64 w-full rounded-xl border border-white/10 bg-[#101820] p-5 font-mono text-sm leading-7 text-white/75 outline-none" placeholder="Write your answer here..." defaultValue={question === 2 ? 'SELECT customer_id, SUM(total) AS lifetime_value\nFROM orders\nGROUP BY customer_id\nORDER BY lifetime_value DESC\nLIMIT 3;' : ''} />}<div className="mt-10 flex items-center justify-between border-t border-white/10 pt-5"><span className="text-xs text-white/35">Your answer saves automatically</span><div className="flex gap-3">{question > 0 && <Button ghost onClick={() => setQuestion(question - 1)}>Previous</Button>}{question < 3 ? <Button onClick={() => setQuestion(question + 1)}>Next question <ArrowRight className="size-4" /></Button> : <Button onClick={() => nav('home')}>Submit assessment <Send className="size-4" /></Button>}</div></div></div></section></div>{paused && <div className="absolute inset-0 grid place-items-center bg-[#080d13]/90 p-5 backdrop-blur-md"><div className="max-w-md rounded-2xl border border-amber-300/30 bg-[#151d25] p-7 text-center"><Radio className="mx-auto size-8 text-amber-300" /><h2 className="mt-5 text-xl font-semibold">Session paused</h2><p className="mt-2 text-sm leading-6 text-white/50">Your current question is frozen. Resume when you’re ready.</p><Button onClick={() => setPaused(false)}>Resume assessment</Button></div></div>}</div> }
function CodeMatesBrief({ nav }: { nav: (v: View) => void }) { return <div className="mx-auto max-w-5xl"><Back onClick={() => nav('codemates')} label="CodeMates arcade" /><div className="grid gap-8 lg:grid-cols-[1fr_.7fr]"><section><Kicker pink>Round briefing · Step 1 of 2</Kicker><h1 className="font-mono text-4xl font-bold tracking-tight sm:text-6xl">Build the app.<br /><span className="text-fuchsia-300">Earn your rank.</span></h1><p className="mt-5 max-w-xl text-base leading-7 text-white/55">Everyone gets the same prompt. Write the clearest code, ship the strongest solution, and climb the room leaderboard.</p><div className="mt-8 border-2 border-[#5b4635] bg-[#f2b84b] p-5 text-[#151515] shadow-[5px_5px_0_#d9362b]"><div className="font-mono text-xs font-bold uppercase tracking-[.2em]">Today&apos;s challenge</div><h2 className="mt-3 font-mono text-2xl font-bold">Build a resilient task board</h2><p className="mt-3 text-sm leading-6 text-[#151515]/75">Create a small app where teammates can add, complete, filter, and reorder tasks. Focus on a clean data model and useful edge-case handling.</p><div className="mt-5 grid gap-2 text-xs font-semibold sm:grid-cols-3"><span className="border-2 border-[#5b4635] bg-[#fffaf0] px-3 py-2">45 MINUTES</span><span className="border-2 border-[#5b4635] bg-[#fffaf0] px-3 py-2">4 PLAYERS</span><span className="border-2 border-[#5b4635] bg-[#fffaf0] px-3 py-2">LIVE SCORING</span></div></div><Button pink onClick={() => nav('codemates-check')}><ShieldCheck className="size-4" />Continue to setup <ArrowRight className="size-4" /></Button></section><aside className="border-2 border-[#5b4635] bg-[#211722] p-5 shadow-[5px_5px_0_#f2b84b]"><div className="font-mono text-xs uppercase tracking-[.2em] text-fuchsia-300">How points work</div><div className="mt-5 grid gap-4">{[['+250', 'Pass all tests'], ['+150', 'Clean, readable code'], ['+100', 'Helpful collaboration'], ['−120', 'Broken or unsafe changes']].map(([score, label]) => <div className="flex items-center justify-between border-b border-white/10 pb-3" key={label}><span className={`font-mono text-xl font-bold ${score.startsWith('−') ? 'text-[#d9362b]' : 'text-[#f2b84b]'}`}>{score}</span><span className="text-right text-xs text-white/55">{label}</span></div>)}</div><p className="mt-6 text-xs leading-5 text-white/35">Your final rank combines correctness, code quality, and teamwork. Scores update after each test run.</p></aside></div></div> }

function CodeMatesCheck({ ready, setReady, nav }: { ready: boolean; setReady: (v: boolean) => void; nav: (v: View) => void }) { const checks = [['Camera access', Video], ['Microphone access', Bell], ['Fullscreen mode', Code2], ['Stable connection', Wifi]] as const; return <div className="mx-auto max-w-4xl"><Back onClick={() => nav('codemates-brief')} label="Round briefing" /><div className="text-center"><Kicker pink>Player setup · Step 2 of 2</Kicker><h1 className="font-mono text-4xl font-bold tracking-tight sm:text-5xl">Lock in your setup.</h1><p className="mx-auto mt-4 max-w-xl text-white/50">Enable the essentials before the prompt appears. This keeps the round fair for everyone in the room.</p></div><div className="mt-10 grid gap-5 md:grid-cols-[.8fr_1.2fr]"><div className="border-2 border-[#5b4635] bg-[#211722] p-5 shadow-[5px_5px_0_#d9362b]"><div className="grid aspect-video place-items-center border-2 border-[#5b4635] bg-[#151515]"><Video className="size-12 text-[#f2b84b]" /></div><div className="mt-4 font-mono text-xs uppercase tracking-widest text-fuchsia-300">Preview ready</div><p className="mt-2 text-sm leading-6 text-white/50">Your camera preview will appear here once permissions are enabled.</p></div><div className="border-2 border-[#5b4635] bg-[#111923] p-5">{checks.map(([label, Icon]) => <div className="flex items-center justify-between border-b border-white/10 py-4" key={label}><div className="flex items-center gap-3"><Icon className="size-4 text-[#f2b84b]" /><span className="text-sm">{label}</span></div><span className="font-mono text-xs text-cyan-300">READY</span></div>)}<label className="mt-5 flex cursor-pointer items-start gap-3 text-xs leading-5 text-white/45"><input type="checkbox" checked={ready} onChange={e => setReady(e.target.checked)} className="mt-1 accent-[#f2b84b]" />I understand the round is timed and my activity may be reviewed for fairness.</label><Button pink disabled={!ready} onClick={() => nav('game')}><Play className="size-4 fill-current" />Show challenge</Button>{!ready && <p className="mt-3 text-xs text-amber-300">Check the consent box to continue.</p>}</div></div></div> }

function CodeMatesHome({ nav, joinLobby }: { nav: (v: View) => void; joinLobby: (code: string) => void }) { const [code, setCode] = useState(''); return <div className="mx-auto max-w-6xl"><Back onClick={() => nav('home')} label="Workspace" /><section className="py-10 text-center"><Kicker pink>Multiplayer coding arcade</Kicker><h1 className="font-mono text-4xl font-bold tracking-[-.06em] sm:text-7xl">MAKE. BREAK.<br /><span className="text-fuchsia-300">REPEAT.</span></h1><p className="mx-auto mt-5 max-w-xl text-sm leading-7 text-white/50">A shared terminal for people who learn by doing. Pick a room, invite your crew, and ship something together.</p><div className="mx-auto mt-8 grid max-w-2xl gap-4 md:grid-cols-2"><div className="border-2 border-[#5b4635] bg-[#d9362b] p-5 text-left shadow-[4px_4px_0_#f2b84b]"><div className="font-mono text-xs uppercase tracking-[.2em] text-[#fffaf0]">Create a room</div><p className="mt-2 text-sm leading-6 text-[#fffaf0]/80">Set up a lobby, invite players, share the code, then start the round.</p><Button onClick={() => nav('codemates-brief')}><Plus className="size-4" />Create room</Button></div><div className="border-2 border-[#5b4635] bg-[#f2b84b] p-5 text-left text-[#151515] shadow-[4px_4px_0_#d9362b]"><div className="font-mono text-xs uppercase tracking-[.2em]">Join with code</div><p className="mt-2 text-sm leading-6 text-[#151515]/75">Enter the room code from your teammate to join their lobby.</p><div className="mt-4 flex gap-2"><input aria-label="Lobby code" value={code} onChange={e => setCode(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') joinLobby(code) }} placeholder="ASYNC-77" className="min-w-0 flex-1 border-2 border-[#5b4635] bg-[#fffaf0] px-3 py-3 font-mono text-sm uppercase text-[#151515] placeholder:text-[#685744]" /><Button onClick={() => joinLobby(code)}>Join</Button></div></div></div></section><div className="mt-5 flex justify-center"><Button ghost onClick={() => nav('rooms')}><Users className="size-4" />Browse live rooms</Button></div><div className="grid gap-5 md:grid-cols-3"><div className="rounded-xl border border-fuchsia-300/25 bg-[#211722] p-5 md:col-span-2"><div className="flex items-center justify-between"><Kicker pink>Live rooms</Kicker><span className="text-xs text-cyan-300">● 18 players online</span></div><div className="mt-2 grid gap-3 sm:grid-cols-2">{[['ASYNC-77', 'Bug bash', '3 / 4', 'Hard'], ['PIXEL-12', 'UI speedrun', '2 / 4', 'Medium'], ['LOOP-09', 'Data structures', '4 / 4', 'Expert'], ['SHIP-42', 'Open build', '1 / 4', 'Chill']].map(([code, name, count, diff]) => <button onClick={() => nav('lobby')} key={code} className="flex items-center justify-between rounded-lg border border-white/10 bg-black/10 p-4 text-left hover:border-fuchsia-300/40"><div><div className="font-mono text-xs text-fuchsia-300">{code}</div><div className="mt-1 text-sm font-semibold">{name}</div></div><div className="text-right text-xs text-white/40"><div>{count} players</div><div className="mt-1">{diff}</div></div></button>)}</div></div><div className="rounded-xl border border-white/10 bg-white/[.03] p-5"><Kicker>Top builders</Kicker>{players.map((p, i) => <div className="mt-4 flex items-center gap-3" key={p.name}><span className="font-mono text-xs text-white/30">0{i + 1}</span><span className={`grid size-8 place-items-center rounded-md text-xs font-bold text-[#101014] ${p.color}`}>{p.initials}</span><div className="flex-1"><div className="text-sm">{p.name}</div><div className="text-xs text-white/35">{p.score} pts</div></div><Trophy className="size-4 text-amber-300" /></div>)}</div></div></div> }
function LiveRooms({ nav, joinLobby }: { nav: (v: View) => void; joinLobby: (code: string) => void }) { const rooms = [{ code: 'ASYNC-77', title: 'Bug Bash', host: 'Maya Chen', players: '3 / 4', difficulty: 'Hard', status: '1 spot left' }, { code: 'PIXEL-12', title: 'Pixel Perfect', host: 'Alex Rivera', players: '2 / 4', difficulty: 'Medium', status: '2 spots left' }, { code: 'STACK-04', title: 'Stack Attack', host: 'Jordan Lee', players: '4 / 4', difficulty: 'Expert', status: 'Starting soon' }]; return <div className="mx-auto max-w-5xl"><Back onClick={() => nav('codemates')} label="CodeMates arcade" /><div className="flex flex-col gap-3 border-b-2 border-[#5b4635] pb-6 sm:flex-row sm:items-end sm:justify-between"><div><Kicker pink>Live rooms</Kicker><h1 className="font-mono text-4xl font-bold tracking-tight sm:text-6xl">Find your crew.</h1><p className="mt-3 max-w-xl text-sm leading-6 text-white/55">Join an open lobby and jump into the next coding round.</p></div><div className="font-mono text-xs uppercase tracking-widest text-[#f2b84b]">{rooms.length} rooms online</div></div><div className="mt-6 grid gap-3">{rooms.map(room => <div key={room.code} className="flex flex-col gap-5 border-2 border-[#5b4635] bg-[#211722] p-5 shadow-[4px_4px_0_#d9362b] sm:flex-row sm:items-center"><div className="grid size-12 shrink-0 place-items-center border-2 border-[#f2b84b] bg-[#151515] font-mono text-xs font-bold text-[#f2b84b]">{room.code.slice(0, 2)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-3"><h2 className="font-mono text-xl font-bold">{room.title}</h2><span className="border border-[#f2b84b] px-2 py-1 font-mono text-[10px] uppercase tracking-widest text-[#f2b84b]">{room.status}</span></div><p className="mt-2 text-xs uppercase tracking-wider text-white/45">Hosted by {room.host} · {room.difficulty} · {room.players} players</p></div><Button pink onClick={() => joinLobby(room.code)}><Users className="size-4" />Join lobby</Button></div>)}</div></div> }

 function Lobby({ nav, roomCode }: { nav: (v: View) => void; roomCode: string }) { const [shareOpen, setShareOpen] = useState(false); const [copied, setCopied] = useState(false); const copyRoomCode = async () => { await navigator.clipboard.writeText(roomCode); setCopied(true); setTimeout(() => setCopied(false), 1800) }; return <div className="mx-auto max-w-5xl"><Back onClick={() => nav('codemates')} label="Leave lobby" /><div className="grid gap-5 lg:grid-cols-[1fr_.65fr]"><div className="rounded-xl border border-fuchsia-300/25 bg-[#211722] p-6"><Kicker pink>Room lobby</Kicker><div className="flex items-center justify-between"><div><h1 className="font-mono text-3xl font-bold">{roomCode}</h1><p className="mt-2 text-sm text-white/45">Bug bash · Hard · 30 minutes</p></div><Button ghost onClick={() => setShareOpen(true)}><Copy className="size-4" />Share code</Button></div><div className="mt-8 grid gap-3">{players.map((p, i) => <div key={p.name} className="flex items-center gap-4 rounded-lg border border-white/10 bg-black/10 p-4"><span className={`grid size-10 place-items-center rounded-md text-xs font-bold text-[#101014] ${p.color}`}>{p.initials}</span><div className="flex-1"><div className="text-sm font-semibold">{p.name}</div><div className="text-xs text-white/35">{i === 0 ? 'Host' : p.status}</div></div><span className="rounded-full bg-cyan-300/10 px-2 py-1 text-[10px] uppercase tracking-wider text-cyan-300">Ready</span></div>)}</div><Button pink onClick={() => nav('game')}>Start round <Play className="size-4 fill-current" /></Button></div><aside className="rounded-xl border border-white/10 bg-[#111923] p-6"><Kicker>Round settings</Kicker>{[['Mode', 'Bug bash'], ['Difficulty', 'Hard'], ['Duration', '30 minutes'], ['Team size', '4 players']].map(([a, b]) => <div key={a} className="flex items-center justify-between border-b border-white/8 py-3 text-sm"><span className="text-white/40">{a}</span><span>{b}</span></div>)}<div className="mt-6 rounded-lg border border-amber-300/20 bg-amber-300/5 p-3 text-xs leading-5 text-amber-200/70"><Radio className="mb-2 size-4" />Host controls stay available during the round.</div></aside></div>{shareOpen && (<div className="fixed inset-0 z-50 grid place-items-center bg-[#10131d]/80 p-5" role="dialog" aria-modal="true" aria-labelledby="share-code-title"><div className="w-full max-w-md border-4 border-[#5b4635] bg-[#f4ead0] p-6 text-[#151515] shadow-[8px_8px_0_#d9362b]"><div className="flex items-start justify-between gap-4"><div><div className="font-mono text-[11px] uppercase tracking-[.2em] text-[#685744]">Invite your crew</div><h2 id="share-code-title" className="mt-2 font-mono text-2xl font-bold">Share this lobby</h2></div><button aria-label="Close share code dialog" onClick={() => setShareOpen(false)} className="grid size-9 place-items-center border-2 border-[#5b4635] hover:bg-[#f2b84b]"><X className="size-4" /></button></div><p className="mt-5 text-sm leading-6 text-[#685744]">Give this code to your teammates so they can join your live room.</p><div className="mt-5 flex items-center gap-2 border-2 border-[#5b4635] bg-[#fffaf0] p-2"><div className="min-w-0 flex-1 px-2 font-mono text-xl font-bold tracking-[.16em]">{roomCode}</div><button onClick={copyRoomCode} className="inline-flex items-center gap-2 border-2 border-[#151515] bg-[#151515] px-3 py-3 font-mono text-xs font-bold text-[#f2b84b] hover:bg-[#d9362b] hover:text-[#fffaf0]"><Copy className="size-4" />{copied ? 'Copied' : 'Copy'}</button></div><button onClick={() => setShareOpen(false)} className="mt-5 w-full border-2 border-[#5b4635] px-4 py-3 font-mono text-xs font-bold uppercase tracking-widest hover:bg-[#f2b84b]">Done</button></div></div>)}</div> }
function LegacyGame({ chat, setChat, messages, sendMessage, nav }: { chat: string; setChat: (v: string) => void; messages: string[]; sendMessage: () => void; nav: (v: View) => void }) { return <div className="mx-auto max-w-[1380px]"><div className="mb-4 flex items-center justify-between font-mono text-xs"><div><span className="text-fuchsia-300">ASYNC-77</span><span className="mx-3 text-white/30">/</span><span className="text-white/50">bug_bash.ts</span></div><div className="flex gap-4"><span className="text-amber-300">18:42</span><span className="text-cyan-300">● connected</span></div></div><div className="grid gap-3 xl:grid-cols-[220px_1fr_260px]"><aside className="rounded-lg border border-white/10 bg-[#111923] p-4"><div className="mb-4 font-mono text-xs text-white/50">PLAYERS</div>{players.map(p => <div className="mb-4 flex items-center gap-2" key={p.name}><span className={`grid size-7 place-items-center rounded text-[10px] font-bold text-[#101014] ${p.color}`}>{p.initials}</span><div className="min-w-0 flex-1"><div className="truncate text-xs">{p.name}</div><div className="text-[10px] text-white/35">{p.status}</div></div><span className="font-mono text-[10px] text-cyan-300">{p.score}</span></div>)}<div className="mt-6 border-t border-white/10 pt-4"><div className="font-mono text-[10px] text-white/35">TEST CASES</div>{['handles empty queue', 'retries on timeout', 'preserves ordering'].map((x, i) => <div className="mt-3 flex items-center gap-2 text-xs text-white/55" key={x}><span className={`grid size-4 place-items-center rounded-full ${i === 0 ? 'bg-cyan-300 text-black' : 'border border-white/20'}`}>{i === 0 && <Check className="size-3" />}</span>{x}</div>)}</div></aside><section className="min-h-[560px] overflow-hidden rounded-lg border border-white/10 bg-[#101820]"><div className="flex items-center justify-between border-b border-white/10 bg-[#18232b] px-4 py-3 font-mono text-xs text-white/45"><span>bug_bash.ts</span><button onClick={() => nav('results')} className="rounded bg-cyan-300 px-3 py-1 font-semibold text-black">Run tests</button></div><div className="flex min-h-[480px] font-mono text-sm leading-7"><div className="w-10 shrink-0 border-r border-white/5 bg-black/10 p-4 text-right text-white/20">{Array.from({ length: 16 }, (_, i) => <div key={i}>{i + 1}</div>)}</div><pre className="overflow-x-auto p-4 text-white/75"><code><span className="text-fuchsia-300">export async function</span> <span className="text-cyan-300">drainQueue</span>(queue) {'{'}{`\n`}  <span className="text-white/40">// keep ordering while retrying transient failures</span>{`\n`}  <span className="text-fuchsia-300">const</span> results = [];{`\n`}  <span className="text-fuchsia-300">while</span> (queue.length) {'{'}{`\n`}    <span className="text-fuchsia-300">const</span> item = queue.shift();{`\n`}    results.push(<span className="text-fuchsia-300">await</span> process(item));{`\n`}  {'}'}{`\n`}  <span className="text-fuchsia-300">return</span> results;{`\n`}{'}'}</code></pre></div></section><aside className="flex min-h-[560px] flex-col rounded-lg border border-white/10 bg-[#111923] p-4"><div className="border-b border-white/10 pb-3 font-mono text-xs text-white/50">CHAT</div><div className="flex-1 space-y-4 py-4">{messages.map((m, i) => <div className="text-xs leading-5 text-white/60" key={`${m}-${i}`}>{m}</div>)}</div><div className="flex gap-2 border-t border-white/10 pt-3"><input value={chat} onChange={e => setChat(e.target.value)} onKeyDown={e => e.key === 'Enter' && !e.nativeEvent.isComposing && sendMessage()} placeholder="Message team..." className="min-w-0 flex-1 bg-transparent text-xs outline-none placeholder:text-white/25" /><button onClick={sendMessage} className="text-cyan-300"><Send className="size-4" /></button></div></aside></div></div> }
function Game({ chat, setChat, messages, sendMessage, nav }: { chat: string; setChat: (v: string) => void; messages: string[]; sendMessage: () => void; nav: (v: View) => void }) {
  const [code, setCode] = useState(`class Counter:\n    def __init__(self):\n        self.count = 0\n\n    def increment(self, amount):\n        if amount <= 0:\n            return False\n        self.count += amount\n        return True\n\n    def decrement(self, amount):\n        if amount <= 0 or amount > self.count:\n            return False\n        self.count -= amount\n        return True\n\n# TODO: reset count to zero\ndef reset(self):\n    pass\n\nprint('Ready to ship')`)
  const [language, setLanguage] = useState('python')
  return <div className="mx-auto max-w-[1380px]">
    <div className="mb-4 flex flex-wrap items-center justify-between gap-3 font-mono text-xs"><div><span className="text-fuchsia-300">ASYNC-77</span><span className="mx-3 text-white/30">/</span><span className="text-white/50">shared_editor</span></div><div className="flex gap-4"><span className="text-amber-300">18:42</span><span className="text-cyan-300">● connected</span></div></div>
    <div className="mb-3 border-2 border-[#5b4635] bg-[#f2b84b] px-4 py-3 text-[#151515] shadow-[4px_4px_0_#d9362b]"><div className="flex flex-wrap items-center gap-x-4 gap-y-1"><span className="font-mono text-[10px] font-bold uppercase tracking-[.2em]">Challenge</span><span className="font-mono text-sm font-bold">Build a resilient task board</span><span className="text-xs text-[#151515]/70">Add, complete, filter, and reorder tasks with clear edge-case handling.</span></div></div>
    <div className="grid gap-3 xl:grid-cols-[220px_1fr_260px]">
      <aside className="rounded-lg border border-white/10 bg-[#111923] p-4"><div className="mb-4 font-mono text-xs text-white/50">PLAYERS</div>{players.map(p => <div className="mb-4 flex items-center gap-2" key={p.name}><span className={`grid size-7 place-items-center rounded text-[10px] font-bold text-[#101014] ${p.color}`}>{p.initials}</span><div className="min-w-0 flex-1"><div className="truncate text-xs">{p.name}</div><div className="text-[10px] text-white/35">{p.status}</div></div><span className="font-mono text-[10px] text-cyan-300">{p.score}</span></div>)}<div className="mt-6 border-t border-white/10 pt-4"><div className="font-mono text-[10px] text-white/35">TEST CASES</div>{['handles empty queue', 'retries on timeout', 'preserves ordering'].map((x, i) => <div className="mt-3 flex items-center gap-2 text-xs text-white/55" key={x}><span className={`grid size-4 place-items-center rounded-full ${i === 0 ? 'bg-cyan-300 text-black' : 'border border-white/20'}`}>{i === 0 && <Check className="size-3" />}</span>{x}</div>)}</div></aside>
      <section className="min-h-[560px] overflow-hidden rounded-lg border border-white/10 bg-[#101820]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 bg-[#18232b] px-4 py-3 font-mono text-xs text-white/45"><div className="flex items-center gap-3"><span>shared_editor</span><select aria-label="Code language" value={language} onChange={e => setLanguage(e.target.value)} className="border border-white/15 bg-[#101820] px-2 py-1 text-[10px] uppercase text-white/65"><option value="python">Python</option><option value="javascript">JavaScript</option><option value="typescript">TypeScript</option></select></div><span className="text-cyan-300">Auto-saved</span></div><Editor height="500px" language={language} theme="vs-dark" value={code} onChange={value => setCode(value ?? '')} options={{ minimap: { enabled: false }, fontSize: 14, padding: { top: 18 }, wordWrap: 'on', automaticLayout: true, scrollBeyondLastLine: false }} /><div className="flex items-center justify-between border-t border-white/10 bg-[#18232b] px-4 py-3"><span className="font-mono text-[10px] uppercase tracking-widest text-white/35">{code.split('\\n').length} lines · editable</span><button onClick={() => nav('results')} className="border-2 border-[#f2b84b] bg-[#d9362b] px-4 py-2 font-mono text-xs font-bold uppercase text-white hover:bg-[#ed4538]">Run tests <Play className="ml-2 inline size-3 fill-current" /></button></div></section>
      <aside className="flex min-h-[560px] flex-col rounded-lg border border-white/10 bg-[#111923] p-4"><div className="mb-4 flex items-center justify-between font-mono text-xs text-white/50"><span>CHAT</span><span className="text-cyan-300">3 online</span></div><div className="grid flex-1 content-start gap-3">{messages.map((message, index) => <div className="border-l-2 border-fuchsia-300/60 pl-3 text-xs leading-5 text-white/60" key={`${message}-${index}`}>{message}</div>)}</div><div className="mt-4 flex gap-2"><input aria-label="Chat message" value={chat} onChange={e => setChat(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') sendMessage() }} placeholder="Type a message..." className="min-w-0 flex-1 border border-white/15 bg-[#101820] px-3 py-2 text-xs text-white placeholder:text-white/30" /><button aria-label="Send message" onClick={sendMessage} className="grid size-9 place-items-center bg-fuchsia-400 text-[#190b1b]"><Send className="size-4" /></button></div></aside>
    </div>
  </div>
}
function Results({ nav }: { nav: (v: View) => void }) { return <div className="mx-auto max-w-4xl py-10 text-center"><div className="mx-auto grid size-16 place-items-center rounded-full bg-cyan-300 text-[#061017]"><Trophy className="size-7" /></div><Kicker>Round complete</Kicker><h1 className="font-mono text-4xl font-bold">NICE SHIP.</h1><p className="mt-3 text-white/50">You made it through the bug bash with a little help from your crew.</p><div className="mx-auto mt-10 grid max-w-2xl gap-3 sm:grid-cols-3">{[['1,240', 'team score'], ['+340', 'your contribution'], ['3 / 3', 'tests passed']].map(([a, b]) => <div className="rounded-xl border border-white/10 bg-white/[.03] p-5" key={b}><div className="font-mono text-2xl font-bold text-cyan-300">{a}</div><div className="mt-2 text-xs uppercase tracking-widest text-white/35">{b}</div></div>)}</div><div className="mt-8 flex justify-center gap-3"><Button ghost onClick={() => nav('codemates')}>Back to arcade</Button><Button pink onClick={() => nav('home')}>Return to workspace <ArrowRight className="size-4" /></Button></div></div> }

function AdminPortal({ nav }: { nav: (v: View) => void }) {
  const [selected, setSelected] = useState('Maya Chen')
  const candidates = [{ name: 'Maya Chen', role: 'Frontend Engineer', score: 94, integrity: 'Clear', submitted: '12 min ago', strengths: 'Debugging, communication', email: 'maya.chen@example.com' }, { name: 'Alex Rivera', role: 'Frontend Engineer', score: 88, integrity: 'Review', submitted: '34 min ago', strengths: 'Architecture, testing', email: 'alex.rivera@example.com' }, { name: 'Jordan Lee', role: 'Frontend Engineer', score: 81, integrity: 'Flagged', submitted: '1 hr ago', strengths: 'Problem solving, SQL', email: 'jordan.lee@example.com' }]
  const candidate = candidates.find(item => item.name === selected) ?? candidates[0]
  return <div className="mx-auto max-w-6xl"><Back onClick={() => nav('hireme')} label="Back to HireMe" /><div className="flex flex-col gap-5 border-b-2 border-[#5b4635] pb-6 sm:flex-row sm:items-end sm:justify-between"><div><Kicker>Recruiter workspace</Kicker><h1 className="font-mono text-4xl font-bold tracking-tight sm:text-6xl">Candidate review.</h1><p className="mt-3 max-w-xl text-sm leading-6 text-white/55">Rank applicants by assessment signal, then inspect integrity events before you reach out.</p></div><div className="border-2 border-[#f2b84b] bg-[#151515] px-4 py-3 font-mono text-xs text-[#f2b84b]">FRONTEND ENGINEER · 12 APPLICANTS</div></div><div className="mt-6 grid gap-5 lg:grid-cols-[1.05fr_.95fr]"><section className="border-2 border-[#5b4635] bg-[#211722] p-4 shadow-[4px_4px_0_#d9362b]"><div className="flex items-center justify-between border-b border-white/10 pb-4"><div className="font-mono text-xs uppercase tracking-widest text-white/45">Ranked applications</div><span className="text-xs text-cyan-300">Updated just now</span></div><div className="mt-3 grid gap-2">{candidates.map((item, index) => <button key={item.name} onClick={() => setSelected(item.name)} className={`grid grid-cols-[32px_1fr_auto] items-center gap-3 border-2 p-3 text-left transition ${selected === item.name ? 'border-[#f2b84b] bg-[#151515]' : 'border-transparent bg-black/10 hover:border-white/20'}`}><span className="font-mono text-lg text-[#f2b84b]">{String(index + 1).padStart(2, '0')}</span><span><span className="block text-sm font-semibold text-white">{item.name}</span><span className="mt-1 block text-xs text-white/40">{item.role} · {item.submitted}</span></span><span className="text-right"><span className="block font-mono text-xl font-bold text-[#f2b84b]">{item.score}</span><span className={`text-[10px] uppercase tracking-widest ${item.integrity === 'Clear' ? 'text-cyan-300' : item.integrity === 'Review' ? 'text-[#f2b84b]' : 'text-[#d9362b]'}`}>{item.integrity}</span></span></button>)}</div></section><aside className="border-2 border-[#5b4635] bg-[#f6edcf] p-5 text-[#151515]"><div className="flex items-start justify-between gap-3"><div><div className="font-mono text-xs uppercase tracking-widest text-[#685744]">Selected candidate</div><h2 className="mt-2 font-mono text-2xl font-bold">{candidate.name}</h2><p className="mt-1 text-sm text-[#685744]">{candidate.role}</p></div><div className="grid size-14 place-items-center border-2 border-[#151515] bg-[#f2b84b] font-mono text-xl font-bold">{candidate.score}</div></div><div className="mt-6 grid gap-3 border-y-2 border-[#cbbd9d] py-4 text-sm"><div className="flex justify-between"><span className="text-[#685744]">Integrity status</span><strong className={candidate.integrity === 'Flagged' ? 'text-[#d9362b]' : 'text-[#151515]'}>{candidate.integrity}</strong></div><div className="flex justify-between"><span className="text-[#685744]">Assessment</span><strong>4 / 4 complete</strong></div><div className="flex justify-between"><span className="text-[#685744]">Strengths</span><strong className="max-w-[55%] text-right">{candidate.strengths}</strong></div></div><div className="mt-5 border-2 border-[#cbbd9d] bg-[#fffaf0] p-3 text-xs leading-5 text-[#685744]"><strong className="text-[#151515]">Integrity review:</strong> {candidate.integrity === 'Clear' ? 'No suspicious activity detected in the recorded session.' : candidate.integrity === 'Review' ? 'One focus change was detected. Review the timeline before deciding.' : 'Multiple focus changes and paste events require manual review.'}</div><div className="mt-5 flex flex-wrap gap-2"><button className="bg-[#151515] px-4 py-3 text-sm font-semibold text-[#fffaf0] hover:bg-[#2d2d2d]">Contact candidate</button><button className="border-2 border-[#151515] px-4 py-3 text-sm font-semibold hover:bg-[#f2b84b]">View assessment</button></div><p className="mt-4 text-[10px] uppercase tracking-widest text-[#685744]">{candidate.email}</p></aside></div><div className="mt-5 border border-[#5b4635] bg-[#151515] p-4 text-xs leading-5 text-white/55"><strong className="text-[#f2b84b]">Prototype note:</strong> rankings and integrity labels are sample review data because no database or authentication integration is connected yet. They are not an authoritative cheating determination.</div></div>
}
